  // 双向锯齿距离 — 1 在格线处 / 0 在格心 → smoothstep 直接接格线（阈值 0.85 = 线宽占周期 15%）
  let g = abs(fract(in.uv / GROUND_CELL) - 0.5) * 2.0;
  let line = smoothstep(0.85, 1.0, max(g.x, g.y));
